#!/usr/bin/env python3
import os, re, glob
NINJA=os.environ.get("NINJA","/tmp/llvm22_build/build.ninja")
SRCROOT=os.environ.get("LLVM_SRCROOT","/tmp/llvm22")
LIBDIR="external/apache2/llvm/lib"
pat=re.compile(r"CMakeFiles/(?:obj\.)?([A-Za-z0-9_]+)\.dir/[^ ]*\.o: \S+ "
    +re.escape(SRCROOT)+r"/(llvm|clang)/(\S+\.(?:cpp|c))(?:\s|$|\|)")
src_info=[]
for line in open(NINJA):
    if "CMakeFiles/" not in line or ".o: " not in line: continue
    m=pat.search(line)
    if m: src_info.append((m.group(1),m.group(2),m.group(3),os.path.dirname(m.group(3))))
owners=[]; reach={}
ppat=re.compile(r"^\.PATH:\s*\$\{(LLVM_SRCDIR|CLANG_SRCDIR)\}/(\S+)")
for mk in glob.glob(f"{LIBDIR}/*/Makefile"):
    has=False
    for line in open(mk):
        m=ppat.match(line)
        if m:
            comp="llvm" if m.group(1)=="LLVM_SRCDIR" else "clang"
            owners.append((comp,m.group(2).rstrip("/"),mk)); has=True
    if has: reach[mk]=True
# assign: mk -> list of (comp, full_reldir, basename)
assigned={mk:[] for mk in reach}; unowned={}
for tgt,comp,rel,sdir in src_info:
    best=None
    for (c,d,mk) in owners:
        if c!=comp: continue
        if sdir==d or sdir.startswith(d+"/"):
            if best is None or len(d)>len(best[0]): best=(d,mk)
    if best:
        assigned[best[1]].append((comp,sdir,os.path.basename(rel)))
    else:
        u=unowned.setdefault(tgt,{'comp':comp,'items':[]})
        u['items'].append((sdir,os.path.basename(rel)))

SRCDIRVAR={"llvm":"LLVM_SRCDIR","clang":"CLANG_SRCDIR"}
def srcs_block(bnames):
    b=sorted(set(bnames))
    out=["SRCS+=\t"+b[0]+(" \\\n" if len(b)>1 else "\n")]
    for x in b[1:-1]: out.append("\t"+x+" \\\n")
    if len(b)>1: out.append("\t"+b[-1]+"\n")
    return out

# rewrite existing: keep first .PATH set? No -- regenerate .PATH from actual source dirs.
changed=0
for mk,items in assigned.items():
    if not items: continue
    dirs=sorted(set((c,d) for c,d,b in items))
    bnames=[b for c,d,b in items]
    lines=open(mk).readlines(); out=[]; i=0; donepath=False; donesrc=False
    while i<len(lines):
        l=lines[i]
        if l.startswith(".PATH:"):
            if not donepath:
                for c,d in dirs: out.append(f".PATH: ${{{SRCDIRVAR[c]}}}/{d}\n")
                donepath=True
            i+=1; continue
        if re.match(r"^SRCS\s*\+?=", l):
            j=i
            while lines[j].rstrip("\n").endswith("\\"): j+=1
            if re.search(r"\.(cpp|c|inc)\b","".join(lines[i:j+1])):
                if not donesrc: out.extend(srcs_block(bnames)); donesrc=True
                i=j+1; continue
        out.append(l); i+=1
    open(mk,"w").writelines(out); changed+=1

created=[]
for tgt,u in sorted(unowned.items()):
    comp=u['comp']; d=f"{LIBDIR}/lib{tgt}"; os.makedirs(d,exist_ok=True)
    dirs=sorted(set(sd for sd,b in u['items'])); bnames=[b for sd,b in u['items']]
    body=["#\tGenerated by regen-srcs-from-cmake.py for LLVM 22\n\n",f"LIB=\t{tgt}\n\n",
          ".include <bsd.init.mk>\n\n"]
    for sd in dirs: body.append(f".PATH: ${{{SRCDIRVAR[comp]}}}/{sd}\n")
    body.append("\n"); body.extend(srcs_block(bnames))
    body.append("\n.if defined(HOSTLIB)\n.include <bsd.hostlib.mk>\n.else\n.include <bsd.lib.mk>\n.endif\n")
    open(f"{d}/Makefile","w").writelines(body); created.append("lib"+tgt)
print(f"existing_rewritten={changed} new_libs={len(created)}")
